def additions(locale):
    t = lambda en, ko: ko if locale == 'ko' else en

    def table(headers, rows):
        return '<div class="table-scroll" tabindex="0"><table><thead><tr>'+''.join('<th>'+t(*h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in r)+'</tr>' for r in rows)+'</tbody></table></div>'

    def note(en, ko):
        return '<p class="auto-note">'+t(en,ko)+'</p>'

    def form(rows):
        return '<div class="auto-form">'+''.join('<label>'+t(*label)+'<input value="'+t(*value)+'"></label>' for label,value in rows)+'</div>'

    def page(title, intro, body):
        return '<h1>'+t(*title)+'</h1><p class="lead">'+t(*intro)+'</p>'+body

    pages = {}
    body = form([(('Period / grouping','기간 / 집계 단위'),('2026-10 · usage day or month; invoice month separate','2026-10 · 사용 일/월 · 인보이스 월 별도')),(('Project / service / SKU','프로젝트 ID / 서비스 / SKU'),('DEMO-P1 / Compute / DEMO-SKU-A','DEMO-P1 / Compute / DEMO-SKU-A')),(('Charge type / region','청구 유형 / 리전'),('Usage + discount / demo-region','사용 + 할인 / demo-region')),(('Currency / view','통화 / 조회 기준'),('USD / normalized cost · source revision XPL-R1','USD / 정규화 비용 · 원천 버전 XPL-R1'))])
    body += '<h2>'+t('Rows: project → service → SKU · columns: charge type','행: 프로젝트 → 서비스 → SKU · 열: 청구 유형')+'</h2>'
    body += table([('Project / service / SKU','프로젝트 / 서비스 / SKU'),('Usage · USD','사용료 · USD'),('Discount · USD','할인 · USD'),('Net · USD','순비용 · USD')],[['DEMO-P1 / Compute / DEMO-SKU-A','1,000.00','−100.00','900.00'],[t('Filtered total · two source rows','필터 합계 · 원천 2행'),'1,000.00','−100.00','900.00']])
    body += note('XPL-DEMO is an independent synthetic two-row example, not the preceding invoice. Expand a cell to its fixed source rows. Swap approved dimensions or save a view without changing billing. Unknown/unallocated buckets remain visible; this example has none. Separate currencies and units; source-net amounts are never reduced by the same discount again.','XPL-DEMO는 앞선 인보이스와 별개의 합성 원천 2행 예시입니다. 셀에서 고정 원천 행으로 내려갑니다. 집계 축 변경·뷰 저장은 청구 계산을 바꾸지 않습니다. 미확인·미배부 항목을 남기며 이 예시에는 없습니다. 통화·단위를 분리하고 순비용에서 동일 할인을 다시 차감하지 않습니다.')
    body += '<p><a href="#raw-explorer">'+t('Inspect underlying rows','원천 행 보기')+' →</a> · <a href="#cost-differences">'+t('Investigate discrepancies','차이 원인 확인')+' →</a></p>'
    pages['cost-pivot'] = page(('Cost pivot by project, service and SKU','프로젝트·서비스·SKU 비용 피벗'),('XPL-DEMO · customer-authorized scope · USD · read-only design','XPL-DEMO · 고객 허용 범위 · USD · 읽기 전용 시안'),body)

    body = form([(('Row / resource / product search','행 / 리소스 / 제품 검색'),('DEMO-RESOURCE-A · current customer scope','DEMO-RESOURCE-A · 현재 고객 범위')),(('Snapshot / export scope','스냅샷 / 내보내기 범위'),('XPL-R1 · all 2 filtered rows, not current page','XPL-R1 · 현재 페이지가 아닌 필터 전체 2행'))])
    body += table([('Visible row reference','조회용 행 참조'),('Project / SKU / type','프로젝트 / SKU / 유형'),('Usage / amount','사용량 / 금액'),('Lineage','근거')],[['VIEW-ROW-01','DEMO-P1 / DEMO-SKU-A / '+t('usage','사용'),'100 h / USD 1,000.00',t('Approved source projection R1','허용된 원천 조회 R1')],['VIEW-ROW-02','DEMO-P1 / DEMO-SKU-A / '+t('discount','할인'),t('No usage quantity / −USD100.00','사용량 없음 / −USD 100.00'),t('Linked to the first row; not a second usage charge','첫 행에 연결 · 사용료 중복 아님')]])
    body += '<p>'+t('Rows2 · net USD900.00 · immutable source revision XPL-R1. Raw and normalized/calculated values remain separate. The original supplier file is restricted evidence, not an unrestricted customer download.','2행 · 순비용 USD 900.00 · 불변 원천 버전 XPL-R1. 원천 값과 정규화·계산 값을 구분합니다. 공급자 원본 파일은 제한된 근거이며 고객에게 무제한 공개하지 않습니다.')+'</p>'
    body += table([('Export contract','내보내기 기준'),('Requirement','요건')],[[t('Format / precision','형식 / 정밀도'),t('CSV/XLSX · decimal-preserving values, explicit units/currency; protect formula injection','CSV/XLSX · 소수 정밀도 보존·단위·통화 표시 · 수식 주입 방지')],[t('Scope / completeness','범위 / 완전성'),t('Customer/field authorization, filters, source revision, rows, totals and checksum manifest','고객·필드 권한·필터·원천 버전·행 수·합계·체크섬 목록')],[t('Large / asynchronous delivery','대량 / 비동기 전달'),t('Progress, expiry, reauthorization and partial/failure status; never silently truncate','진행·만료·권한 재확인·일부/실패 표시 · 조용한 잘림 금지')]])
    body += '<button disabled>'+t('Export CSV / XLSX · design only','CSV / XLSX 내보내기 · 설계 예시')+'</button>'
    pages['raw-explorer'] = page(('Raw cost lookup and export','로우데이터 조회·내보내기'),('XPL-DEMO · permitted fields only · no live download','XPL-DEMO · 허용된 필드만 · 실제 다운로드 미연결'),body)

    body = table([('Case','사례'),('Compare same scope','동일 범위 비교'),('Diagnosis / required evidence','진단 / 필요한 근거'),('State','상태')],[[t('Small instance difference','인스턴스 소액 차이'),t('Two KRW rows:1.6+1.6=3.2; truncate total3 vs truncate each1+1=2','KRW 2행: 1.6+1.6=3.2 · 합계 절삭3 / 행별 절삭1+1=2'),t('Difference1 explained by stage only after matching period/source; never blanket tolerance','기간·원천 일치 확인 후 절삭 단계 차이1 설명 · 일괄 허용오차 금지'),t('Illustrative; policy review','설명 예시 · 정책 검토')],[t('AI instance version','AI 인스턴스 버전'),t('Resource label same; SKU/version A versus B','리소스명 동일 · SKU/버전 A와 B 상이'),t('Compare model/version/region/unit/effective rate date and frozen source; missing rate stays unknown','모델·버전·리전·단위·요율 적용일·원천 비교 · 누락 단가는 미확인'),t('Blocked: evidence missing','근거 누락 · 보류')],[t('CSP support charge','CSP Support 비용'),t('Console estimate100 / export120 / final invoice120; USD synthetic','콘솔 예상100 / 원천120 / 최종 인보이스120 · USD 합성'),t('Check as-of, covered accounts, fee base/tier/minimum, credits and finalization; change reason not inferred','기준 시각·대상 계정·산정 기준·구간·최소액·크레딧·확정 여부 확인 · 원인 추정 금지'),t('Unexplained20; review','미설명20 · 검토 필요')]])
    body += note('These are three independent examples, not additive discrepancies. Raw stored precision, calculation precision, console display and Excel stored value/format are separate. Confirm document type, currency, tax/FX, scope, revision and as-of before comparing. Keep original evidence; corrections create revisions and issued documents use linked correction, never silent replacement.','서로 독립된 3개 예시이며 차이를 합산하지 않습니다. 원천 저장 정밀도·계산 정밀도·콘솔 표시·Excel 저장값/서식을 구분합니다. 문서 종류·통화·세금/환율·범위·버전·시점을 맞춰 비교합니다. 원본을 보존하고 수정은 새 버전으로, 발행 후에는 연결된 정정으로 처리합니다.')
    body += '<p><a href="#raw-explorer">'+t('View separate XPL-DEMO raw example','별도 XPL-DEMO 원천 조회 예시 보기')+' →</a></p>'
    pages['cost-differences'] = page(('Precision, AI version and support reconciliation','정밀도·AI 버전·Support 금액 대사'),('Evidence first: small differences are not automatically acceptable.','근거 우선 · 소액 차이라고 자동 허용하지 않습니다.'),body)

    body = table([('ISV / product','ISV / 제품'),('Marketplace / reference','Marketplace / 참조'),('Purchase cost','구매 비용'),('Linked agreements','연결 계약'),('Commitment status','약정 충당 상태')],[['DEMO-ISV / AI observability','Azure Marketplace · DEMO-OFFER-01','USD 2,000.00',t('Procurement MP-P1 / customer selling MP-S1; private terms unverified','매입 MP-P1 / 고객 판매 MP-S1 · 비공개 조건 미확인'),t('Eligibility unverified; confirmed credit unknown','적격 미확인 · 확정 충당액 미확인')]])
    body += table([('Required detail','필수 상세'),('Meaning','의미')],[[t('Publisher / offer / plan / order','판매자 / 오퍼 / 플랜 / 주문'),t('Use actual source IDs when supplied; missing metadata stays missing','원천에 있으면 실제 ID 연결 · 없으면 누락 표시')],[t('Transaction / payer / recipient','거래 유형 / 납부자 / 귀속 고객'),t('Direct / partner / private-offer path determines billing responsibility','직접 / 파트너 / 비공개 오퍼 경로에 따라 청구 책임 확인')],[t('Software versus infrastructure','소프트웨어와 인프라'),t('ISV license/usage, underlying GPU/VM/storage and MSP fees remain separate','ISV 라이선스·사용료, 기반 GPU/VM/저장소, MSP 수수료 분리')],[t('Contract PDF evidence','계약 PDF 근거'),t('AI proposes seller/product/term/discount clauses with page references; human confirms ambiguous/missing clauses','AI가 판매자·제품·기간·할인 조항을 페이지와 함께 제안 · 모호·누락 조항은 사람이 확인')],[t('Purchase versus customer price','구매 비용과 고객 제공가'),t('No automatic inheritance of general CSP discounts; customer bill needs its own selling terms','일반 CSP 할인 자동 상속 금지 · 고객 청구는 별도 판매 조건 필요')]])
    body += note('MP-DEMO is separate from other examples. Cost exports may identify publisher/product/order but do not guarantee every negotiated contract term or seller settlement fee. Do not infer EA/EDP eligibility from a Marketplace label. Customer cost detail requires the same approved disclosure scope as other procurement.','MP-DEMO는 다른 예시와 별개입니다. 비용 원천에서 판매자·제품·주문을 식별할 수 있어도 모든 협상 조건·판매자 정산 수수료가 제공되는 것은 아닙니다. Marketplace라는 이유만으로 EA/EDP 충당을 인정하지 않습니다. 고객 원가 상세는 다른 매입 원가와 동일한 공개 권한을 적용합니다.')
    body += '<a href="#marketplace-commitment">'+t('Actual commitment credit / purchase planning','실제 약정 충당 / 구매 계획 보기')+' →</a>'
    pages['marketplace-register'] = page(('Marketplace ISV costs and contracts','Marketplace ISV 비용·계약'),('MP-DEMO · identify ISV purchases clearly, apart from cloud infrastructure.','MP-DEMO · ISV 구매 비용을 클라우드 인프라와 구분해 확인합니다.'),body)

    body = '<h2>'+t('Actual purchase: eligibility and confirmed contribution are separate','실제 구매: 적격 여부와 확정 충당액은 별도')+'</h2>'+table([('Purchase amount','구매액'),('Eligible amount','적격 금액'),('Provider-confirmed credit','공급자 확정 충당액'),('Reason','근거 상태')],[['USD 2,000.00',t('Unknown','미확인'),t('Unknown','미확인'),t('Agreement type, channel, product and eligible date not confirmed','약정 종류·구매 경로·상품·인정 시점 미확인')]])
    body += '<h2>'+t('Optional purchase plan · list-price scenario','선택 확장 · 정가 기준 구매 예정 시뮬레이션')+'</h2>'+form([(('Planned ISV purchase / date','예정 ISV 구매 / 일자'),('DEMO-ISV · USD10,000 list · 2026-11-01','DEMO-ISV · 정가 USD 10,000 · 2026-11-01')),(('Contract / total / consumed','약정 / 총액 / 소진액'),('SIM-COMMIT-01 · USD100,000 / confirmed40,000','SIM-COMMIT-01 · USD 100,000 / 확정 소진40,000'))])
    body += table([('Assumption / result','가정 / 결과'),('Illustration only','가정에 따른 예시만')],[[t('Eligibility / remaining product cap','적격 / 상품 한도 잔여'),t('Assume100% eligible and at least10,000 headroom; not a real EA/EDP rule','100% 적격·한도 잔여10,000 이상을 가정 · 실제 EA/EDP 규칙 아님')],[t('Estimated incremental credit','추가 예상 충당액'),'USD 10,000.00'],[t('Before → after utilization','소진율 변경'),'40% → 50% · +10 '+t('percentage points','%p')],[t('Remaining commitment','잔여 약정액'),'USD 60,000 → USD 50,000'],[t('Without verified eligibility/cap','적격·한도 근거가 없을 때'),t('Needs confirmation; no committed forecast or actual credit','확인 필요 · 확정 예측·실제 충당으로 기록 안 함')]])
    body += note('List-price planning excludes negotiated ISV discounts and is only a scenario. Actual credit may follow invoiced/qualifying price and contract limits. Bind total, remaining commitment, eligible term/channel, currency and cap basis; purchases outside term or exceeding limits must be flagged. Do not add scenarios to the actual ledger, automatically purchase, or equate commitment consumption with a cash discount or prepaid-balance use.','정가 계획은 ISV 협상 할인을 제외한 가정 시나리오입니다. 실제 인정액은 청구·적격 가격과 계약 한도에 따를 수 있습니다. 총액·잔여 약정·기간·경로·통화·한도 기준을 고정하고 기간 밖·한도 초과를 표시합니다. 시나리오를 실제 원장에 더하거나 자동 구매하지 않으며 약정 충당을 현금 할인·선납 잔액 사용과 동일시하지 않습니다.')
    pages['marketplace-commitment'] = page(('Commitment credit and ISV purchase planning','약정 충당 현황·ISV 구매 계획'),('Actual billing evidence and optional forecasts remain separate.','실제 빌링 근거와 선택형 구매 예상 계산을 분리합니다.'),body)
    return pages
